package boltstore

import (
	"context"
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strings"

	bolt "go.etcd.io/bbolt"

	"github.com/Sounabha07/S3-Object-Store/internal/metadata"
)

// NewUploadID returns a random upload ID. It is generated by the proposer,
// never inside Apply, so the state machine stays deterministic.
func NewUploadID() string {
	var b [16]byte
	_, _ = rand.Read(b[:])
	return hex.EncodeToString(b[:])
}

func partKey(n int) []byte {
	var k [4]byte
	binary.BigEndian.PutUint32(k[:], uint32(n)) // #nosec G115 -- n is validated to 1..10000
	return k[:]
}

func getUpload(tx *bolt.Tx, uploadID string) (metadata.UploadInfo, error) {
	var up metadata.UploadInfo
	v := tx.Bucket(bktUploads).Get([]byte(uploadID))
	if v == nil {
		return up, metadata.ErrNoSuchUpload
	}
	return up, json.Unmarshal(v, &up)
}

func createMultipart(tx *bolt.Tx, cmd Command) (result, fatal error) {
	if tx.Bucket(bktBuckets).Get([]byte(cmd.Bucket)) == nil {
		return metadata.ErrNoSuchBucket, nil
	}
	uploads := tx.Bucket(bktUploads)
	if uploads.Get([]byte(cmd.UploadID)) != nil {
		return fmt.Errorf("%w: upload id already exists", metadata.ErrInvalidArgument), nil
	}
	up := metadata.UploadInfo{UploadID: cmd.UploadID, Bucket: cmd.Bucket, Key: cmd.Key, Initiated: cmd.Time}
	if cmd.Upload != nil {
		up.Meta = *cmd.Upload
	}
	v, err := json.Marshal(up)
	if err != nil {
		return nil, err
	}
	if err := uploads.Put([]byte(cmd.UploadID), v); err != nil {
		return nil, err
	}
	_, err = tx.Bucket(bktParts).CreateBucket([]byte(cmd.UploadID))
	return nil, err
}

func putPart(tx *bolt.Tx, cmd Command) (result, fatal error) {
	if _, err := getUpload(tx, cmd.UploadID); err != nil {
		return err, nil
	}
	parts := tx.Bucket(bktParts).Bucket([]byte(cmd.UploadID))
	if parts == nil {
		return metadata.ErrNoSuchUpload, nil
	}
	v, err := json.Marshal(cmd.Part)
	if err != nil {
		return nil, err
	}
	return nil, parts.Put(partKey(cmd.Part.PartNumber), v)
}

func normETag(e string) string { return strings.ToLower(strings.Trim(strings.TrimSpace(e), `"`)) }

func completeMultipart(tx *bolt.Tx, cmd Command) (result, fatal error) {
	up, err := getUpload(tx, cmd.UploadID)
	if err != nil {
		return err, nil
	}
	objects := tx.Bucket(bktObjects).Bucket([]byte(up.Bucket))
	if objects == nil {
		return metadata.ErrNoSuchBucket, nil
	}
	parts := tx.Bucket(bktParts).Bucket([]byte(cmd.UploadID))
	req := cmd.Complete
	obj := metadata.ObjectMeta{
		Bucket: up.Bucket, Key: up.Key, VersionID: req.VersionID,
		ContentType: up.Meta.ContentType, UserMeta: up.Meta.UserMeta, Headers: up.Meta.Headers,
		LastModified: cmd.Time,
	}
	// Order is checked over the whole list first, so the error does not
	// depend on which other problem happens to come earlier.
	prev := 0
	for _, cp := range req.Parts {
		if cp.PartNumber <= prev {
			return metadata.ErrInvalidPartOrder, nil
		}
		prev = cp.PartNumber
	}
	for i, cp := range req.Parts {
		v := parts.Get(partKey(cp.PartNumber))
		if v == nil {
			return fmt.Errorf("%w: part %d was not uploaded", metadata.ErrInvalidPart, cp.PartNumber), nil
		}
		var pm metadata.PartMeta
		if err := json.Unmarshal(v, &pm); err != nil {
			return nil, err
		}
		if normETag(cp.ETag) != normETag(pm.ETag) {
			return fmt.Errorf("%w: part %d ETag does not match", metadata.ErrInvalidPart, cp.PartNumber), nil
		}
		if i < len(req.Parts)-1 && pm.Size < req.MinPartSize {
			return fmt.Errorf("%w: part %d is %d bytes", metadata.ErrEntityTooSmall, cp.PartNumber, pm.Size), nil
		}
		for _, c := range pm.Chunks {
			c.Offset += obj.Size
			obj.Chunks = append(obj.Chunks, c)
		}
		obj.Size += pm.Size
	}
	etag, err := metadata.MultipartETag(req.Parts)
	if err != nil {
		return err, nil
	}
	obj.ETag = etag
	v, err := json.Marshal(obj)
	if err != nil {
		return nil, err
	}
	if err := objects.Put([]byte(obj.Key), v); err != nil {
		return nil, err
	}
	return deleteUpload(tx, cmd.UploadID)
}

func abortMultipart(tx *bolt.Tx, uploadID string) (result, fatal error) {
	if _, err := getUpload(tx, uploadID); err != nil {
		return err, nil
	}
	return deleteUpload(tx, uploadID)
}

func deleteUpload(tx *bolt.Tx, uploadID string) (result, fatal error) {
	if err := tx.Bucket(bktUploads).Delete([]byte(uploadID)); err != nil {
		return nil, err
	}
	if tx.Bucket(bktParts).Bucket([]byte(uploadID)) != nil {
		if err := tx.Bucket(bktParts).DeleteBucket([]byte(uploadID)); err != nil {
			return nil, err
		}
	}
	return nil, nil
}

func abortBucketUploads(tx *bolt.Tx, bucket string) error {
	var ids []string
	err := tx.Bucket(bktUploads).ForEach(func(k, v []byte) error {
		var up metadata.UploadInfo
		if err := json.Unmarshal(v, &up); err != nil {
			return err
		}
		if up.Bucket == bucket {
			ids = append(ids, string(k))
		}
		return nil
	})
	if err != nil {
		return err
	}
	for _, id := range ids {
		if _, err := deleteUpload(tx, id); err != nil {
			return err
		}
	}
	return nil
}

// CreateMultipart implements metadata.Metadata.
func (s *Store) CreateMultipart(ctx context.Context, bucket, key string, m metadata.UploadMeta) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	id := NewUploadID()
	if err := s.Apply(0, Command{Op: OpCreateMultipart, Bucket: bucket, Key: key, UploadID: id, Time: s.now(), Upload: &m}); err != nil {
		return "", err
	}
	return id, nil
}

// GetUpload implements metadata.Metadata.
func (s *Store) GetUpload(ctx context.Context, uploadID string) (metadata.UploadInfo, error) {
	var up metadata.UploadInfo
	if err := ctx.Err(); err != nil {
		return up, err
	}
	err := s.view(func(tx *bolt.Tx) error {
		var err error
		up, err = getUpload(tx, uploadID)
		return err
	})
	return up, err
}

// PutPart implements metadata.Metadata.
func (s *Store) PutPart(ctx context.Context, uploadID string, p metadata.PartMeta) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	return s.Apply(0, Command{Op: OpPutPart, UploadID: uploadID, Part: &p})
}

// ListParts implements metadata.Metadata.
func (s *Store) ListParts(ctx context.Context, uploadID string, opts metadata.ListPartsOptions) (metadata.ListPartsResult, error) {
	var res metadata.ListPartsResult
	if err := ctx.Err(); err != nil {
		return res, err
	}
	maxParts := opts.MaxParts
	if maxParts <= 0 || maxParts > 1000 {
		maxParts = 1000
	}
	err := s.view(func(tx *bolt.Tx) error {
		up, err := getUpload(tx, uploadID)
		if err != nil {
			return err
		}
		res.Bucket, res.Key, res.UploadID = up.Bucket, up.Key, uploadID
		parts := tx.Bucket(bktParts).Bucket([]byte(uploadID))
		if parts == nil {
			return nil
		}
		c := parts.Cursor()
		for k, v := c.Seek(partKey(opts.PartNumberMarker + 1)); k != nil; k, v = c.Next() {
			if len(res.Parts) == maxParts {
				res.IsTruncated = true
				break
			}
			var pm metadata.PartMeta
			if err := json.Unmarshal(v, &pm); err != nil {
				return err
			}
			res.Parts = append(res.Parts, pm)
			res.NextPartNumberMarker = pm.PartNumber
		}
		return nil
	})
	return res, err
}

// CompleteMultipart implements metadata.Metadata.
func (s *Store) CompleteMultipart(ctx context.Context, uploadID string, req metadata.CompleteRequest) (metadata.ObjectMeta, error) {
	if err := ctx.Err(); err != nil {
		return metadata.ObjectMeta{}, err
	}
	up, err := s.GetUpload(ctx, uploadID)
	if err != nil {
		return metadata.ObjectMeta{}, err
	}
	if err := s.Apply(0, Command{Op: OpCompleteMultipart, UploadID: uploadID, Time: s.now(), Complete: &req}); err != nil {
		return metadata.ObjectMeta{}, err
	}
	etag, _ := metadata.MultipartETag(req.Parts)
	return metadata.ObjectMeta{Bucket: up.Bucket, Key: up.Key, VersionID: req.VersionID, ETag: etag}, nil
}

// AbortMultipart implements metadata.Metadata.
func (s *Store) AbortMultipart(ctx context.Context, uploadID string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	return s.Apply(0, Command{Op: OpAbortMultipart, UploadID: uploadID})
}

// WalkPartChunks implements metadata.Metadata.
func (s *Store) WalkPartChunks(ctx context.Context, fn func(uploadID string, partNumber int, c metadata.Chunk) error) error {
	return s.view(func(tx *bolt.Tx) error {
		return tx.Bucket(bktParts).ForEachBucket(func(id []byte) error {
			return tx.Bucket(bktParts).Bucket(id).ForEach(func(_, v []byte) error {
				if err := ctx.Err(); err != nil {
					return err
				}
				var pm metadata.PartMeta
				if err := json.Unmarshal(v, &pm); err != nil {
					return err
				}
				for _, c := range pm.Chunks {
					if err := fn(string(id), pm.PartNumber, c); err != nil {
						return err
					}
				}
				return nil
			})
		})
	})
}
